        for c in range(w - 2):
            color = g[r][c]
            if color == 0:
                continue
            if all(g[rr][cc] == color for rr in range(r, r + 3) for cc in range(c, c + 3)):
                blocks.append((r + 1, c + 1, color))
    for r, c, color in blocks:
        for x in range(w):
            g[r][x] = color
        for y in range(h):
            g[y][c] = color
    return g
